def para(text='',style=None,boldlead=None):
 p=doc.add_paragraph(style=style)
 if boldlead and text.startswith(boldlead):p.add_run(boldlead).bold=True;p.add_run(text[len(boldlead):])
 else:p.add_run(text)
 return p
def heading(text,level=1):doc.add_heading(text,level)
def bullet(text):doc.add_paragraph(text,style='List Bullet')
def table(headers,rows,widths=None):
 t=doc.add_table(rows=1,cols=len(headers));t.style='Light Shading Accent 1';t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for c,txt in zip(t.rows[0].cells,headers): c.text=str(txt);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
 for row in rows:
  cells=t.add_row().cells
  for c,txt in zip(cells,row):c.text=str(txt);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
 return t
